    if turn > 1:
        turn = 1
    if turn < -1:
        turn = -1
    left = 1 - turn
    right = 1 + turn
    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1
    return (left, right)

